[
  {
    "sys_fairness_reciprocity": "That seems more even than me taking five while they walk.",
    "sys_consequence_reasoning": "testifying would add years to their sentence too",
    "pda_responsibility": "my own hands were in that warehouse business",
    "pda_repair_intention": "write out a full account of my part for the court"
  },
  {
    "sys_fairness_reciprocity": "Matching that would even things out, three and three.",
    "pda_responsibility": "I did what I did in that warehouse, and nobody forced me.",
    "pda_repair_intention": "pay back whoever lost something in that case"
  },
  {
    "sys_fairness_reciprocity": "Giving evidence would square that up.",
    "pda_responsibility": "I'd be the one doing that",
    "pda_repair_intention": "tell the judge plainly what I did too"
  },
  {
    "pd_decision_conflict": "My stomach's in knots.",
    "pda_responsibility": "The trouble started with me as much as with them.",
    "sys_fairness_reciprocity": "If I talk, we each carry our share.",
    "pda_repair_intention": "set aside part of whatever I earn later to repay any damage"
  },
  {
    "pda_responsibility": "I know what I knew going in, and I went anyway",
    "sys_fairness_reciprocity": "feels closer to balanced.",
    "pda_repair_intention": "offer to meet whoever the warehouse belonged to"
  },
  {
    "pd_personal_consequence_anxiety": "I'm scared of five years, really scared.",
    "sys_consequence_reasoning": "speaking against them means I help put them away",
    "pda_responsibility": "that would be my doing",
    "sys_fairness_reciprocity": "Maybe it's more even that I take the heavier sentence",
    "pda_repair_intention": "write to the court and correct anything in their account"
  },
  {
    "pd_decision_conflict": "Every time I try to pick, I freeze.",
    "sys_fairness_reciprocity": "choosing the same feels like simply giving back what I got",
    "pda_responsibility": "My choices in that warehouse are part of why",
    "pda_repair_intention": "offer community work to pay something back"
  },
  {
    "sys_fairness_reciprocity": "Talking would even the scales.",
    "sys_consequence_reasoning": "my testimony would be the thing adding three years to them",
    "pda_responsibility": "I can't pretend I'd be a bystander",
    "pda_repair_intention": "explain myself to my family and to anyone hurt"
  },
  {
    "pd_personal_consequence_anxiety": "Five years is a huge chunk.",
    "sys_fairness_reciprocity": "we share the cost equally",
    "sys_consequence_reasoning": "pile years onto another person",
    "pda_responsibility": "I had a part in what happened in that warehouse",
    "pda_repair_intention": "arrange restitution in small installments"
  },
  {
    "pda_responsibility": "I knew what I was getting into at that warehouse",
    "sys_fairness_reciprocity": "why should I serve five while they serve none?",
    "pda_repair_intention": "write a letter to the court owning my part"
  }
]
